package io.tenvyr.control.authority;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import io.tenvyr.platform.*;
import io.tenvyr.platform.domain.ExecutionState;
import io.tenvyr.control.engine.*;
import java.sql.*;
import java.time.Instant;
import java.util.*;

/** Complete engine authority seam; every effect uses the transaction pinned by the engine. */
public final class AuthorityServices implements EngineAuthority {
    public final PolicyService policy;public final BudgetLedgerService budget;public final PlanProposalService plans;public final ApprovalService approvals;public final DelegationService delegation;public final ExecutionStateService state;public final ExecutionCapsuleService capsules;
    private final Db db;private final LinkedHashMap<String,ObjectNode> contextCache=new LinkedHashMap<>(64,.75f,true);private int cacheBytes;
    public AuthorityServices(Db db){this(db,()->System.getenv("TENVYR_POLICY"));}
    public AuthorityServices(Db db,java.util.function.Supplier<String> configuration){this.db=db;policy=new PolicyService(db,configuration);budget=new BudgetLedgerService(db);plans=new PlanProposalService(db,policy);approvals=new ApprovalService(db,budget,plans);delegation=new DelegationService(db,policy);state=new ExecutionStateService(db);capsules=new ExecutionCapsuleService(db,delegation);}
    public void bind(PipelineService pipelines,ExecutionService executions,EngineRuntime runtime,AgentTransportConfig transport){plans.validator(pipelines::validateSteps);approvals.bindRuntime(transport::supportsObserved,runtime::workspaceMetadata);delegation.bindExecutions(executions::materializeExecutionWithManager,id->executions.cancelExecution(id,"Parent execution cancelled"));capsules.bindExecutions(executions::materializeExecutionWithManager);}
    @Override public JsonNode validatePipelineBudget(JsonNode n){return BudgetDomain.pipelineBudget(n);}
    @Override public JsonNode validateStepBudget(JsonNode n){return BudgetDomain.stepBudget(n);}
    @Override public JsonNode validateProjection(JsonNode n){return ContextDomain.validateProjection(n);}
    @Override public JsonNode validateStateWrites(JsonNode n){return StateWritesDomain.validate(n);}
    @Override public ClaimContext projectContext(Connection c,ObjectNode execution,ObjectNode step,ObjectNode executor,ObjectNode revision){try{Db t=Db.on(c);ObjectNode harness=Json.object("agent",step.get("agent"),"executorKind",executor.get("kind"),"configHash",executor.get("configHash"));if(executor.hasNonNull("connection")){harness.set("connectionId",executor.path("connection").get("connectionId"));harness.set("connectionRevision",executor.path("connection").get("revisionNumber"));}if(executor.hasNonNull("requestedModelId"))harness.set("requestedModelId",executor.get("requestedModelId"));ObjectNode run=t.one("SELECT workspace FROM coordination_runs WHERE \"executionId\"=?::uuid",execution.get("id"));JsonNode workspace=run!=null&&run.hasNonNull("workspace")?ContextDomain.workspaceIdentity(run.get("workspace")):null;JsonNode envelope=NullNode.instance,metrics=NullNode.instance,bundle=NullNode.instance;List<String> ids=List.of();JsonNode fullState=execution.hasNonNull("executionState")?execution.get("executionState"):Json.object();int version=Json.integer(execution,"executionStateVersion",0);
        if(step.hasNonNull("contextProjection")){ObjectNode projection=ContextDomain.validateProjection(step.get("contextProjection"));ArrayNode refs=Json.array();if(projection.has("artifacts")){ArtifactProjectionResolver.Resolution resolved=new ArtifactProjectionResolver(c).resolve(Json.text(execution,"id"),projection.get("artifacts"));refs=resolved.references();ids=resolved.artifactIds();}ObjectNode identity=Json.object("bundleSchemaVersion",1,"contextSchemaVersion",1,"stateProjection",Json.object("version",version,"values",ContextDomain.select(projection,fullState)),"artifacts",refs,"harness",harness);if(revision.hasNonNull("planHash"))identity.set("planHash",revision.get("planHash"));if(workspace!=null)identity.set("workspace",workspace);String hash=Json.hash(identity);ObjectNode cached; synchronized(contextCache){cached=contextCache.get(hash);cached=cached==null?null:cached.deepCopy();}boolean reused=cached!=null;if(reused){envelope=cached.get("envelope");ObjectNode m=(ObjectNode)cached.get("metrics");m.put("executionStateBytes",ExecutionState.jsonValueUtf8Size(fullState));metrics=m;}else{envelope=ContextDomain.materialize(projection,fullState,version,refs);metrics=ContextDomain.metrics(envelope,fullState);cache(hash,envelope,(ObjectNode)metrics);}bundle=Json.object("hash",hash,"reused",reused);}
        ObjectNode logical=t.one("SELECT id,attempt,\"startTime\" FROM step_executions WHERE \"executionId\"=?::uuid AND \"stepId\"=?",execution.get("id"),step.get("id"));if(logical==null)throw new IllegalStateException("Claimed logical step disappeared");String invocation=Json.text(logical,"id")+":"+Json.integer(logical,"attempt",1);ObjectNode input=Json.object("invocationId",invocation,"harness",harness,"contextBundle",bundle,"context",metrics,"dispatchable",true,"startedAt",Instant.now().toString());if(workspace!=null)input.set("workspace",workspace);return new ClaimContext(envelope,ids,ContextDomain.claimEvidence(input));}catch(AuthorityError error){throw failure(error,"projection_failed");}catch(IllegalArgumentException error){throw new AuthorityFailure("TENVYR_CTX_INVALID_PROJECTION","projection_failed",error.getMessage());}}
    private void cache(String hash,JsonNode envelope,ObjectNode metrics){int bytes=Json.integer(metrics,"projectedBytes",0);if(bytes>4*1024*1024)return;ObjectNode m=metrics.deepCopy();m.remove("executionStateBytes");synchronized(contextCache){if(contextCache.containsKey(hash))return;contextCache.put(hash,Json.object("envelope",envelope.deepCopy(),"metrics",m,"bytes",bytes));cacheBytes+=bytes;while(contextCache.size()>64||cacheBytes>4*1024*1024){String oldest=contextCache.keySet().iterator().next();cacheBytes-=Json.integer(contextCache.remove(oldest),"bytes",0);}}}
    @Override public JsonNode evaluateDispatch(Connection c,ObjectNode proposal){return policy.isConfigured()?policy.evaluate(proposal,c):null;}
    @Override public void requestApproval(Connection c,ObjectNode p){approvals.request(p,c,3_600_000);}
    @Override public void reserveBudget(Connection c,ObjectNode execution,ObjectNode revision,ObjectNode step,ObjectNode attempt)throws SQLException{Savepoint checkpoint=c.setSavepoint();try{ObjectNode account=budget.ensureExecutionAccount(c,Json.text(execution,"id"),revision.path("plan").get("budget"),step.get("budget"));budget.reserveForAttempt(c,Json.object("executionId",execution.get("id"),"logicalStepId",attempt.get("logicalStepId"),"attemptNumber",attempt.get("attemptNumber"),"invocationId",attempt.get("invocationId"),"accountId",account.get("id"),"budget",step.get("budget")));c.releaseSavepoint(checkpoint);}catch(AuthorityError error){c.rollback(checkpoint);throw failure(error,"budget_insufficient");}}
    @Override public void releaseBudget(Connection c,String ref,String reason){budget.releaseForAction(c,ref,reason);}
    @Override public void settleBudget(Connection c,String ref,JsonNode usage)throws SQLException{Savepoint checkpoint=c.setSavepoint();try{budget.reconcileTerminal(c,ref,usage);c.releaseSavepoint(checkpoint);}catch(AuthorityError error){c.rollback(checkpoint);System.err.println("Result usage reconciliation rejected for invocation "+ref+" code "+error.code);}}
    @Override public JsonNode applyStateWrites(Connection c,ObjectNode execution,JsonNode mappings,JsonNode output){int prior=Json.integer(execution,"executionStateVersion",0);ObjectNode result=Json.object("disposition","rejected","priorVersion",prior,"resultVersion",prior);ObjectNode patch;try{patch=StateWritesDomain.patch(output,mappings);}catch(AuthorityError error){result.put("rejectionCode",error.code);return result;}catch(RuntimeException error){result.put("rejectionCode","TENVYR_STATE_WRITE_INVALID_PATCH");return result;}ObjectNode validated;try{validated=ExecutionState.validateStatePatch(patch);}catch(RuntimeException error){result.put("rejectionCode","TENVYR_STATE_WRITE_INVALID_PATCH");return result;}result.put("mappingHash",Json.hash(validated));ObjectNode applied=ExecutionState.applyStatePatch(execution.hasNonNull("executionState")?execution.get("executionState"):Json.object(),validated);if(!applied.path("changed").asBoolean()){result.put("disposition","noop");return result;}JsonNode state=applied.get("state");int bytes;try{bytes=ExecutionState.jsonValueUtf8Size(state);}catch(RuntimeException error){result.put("rejectionCode","TENVYR_STATE_WRITE_UNSAFE_VALUE");return result;}if(bytes>ExecutionState.MAX_STATE_BYTES||state.size()>ExecutionState.MAX_STATE_KEYS){result.put("rejectionCode","TENVYR_STATE_WRITE_BOUNDS");return result;}String updated=Instant.now().toString();Db.on(c).execute("UPDATE executions SET \"executionState\"=?,\"executionStateVersion\"=?,\"executionStateUpdatedAt\"=?,\"rowVersion\"=\"rowVersion\"+1,\"updatedAt\"=now() WHERE id=?::uuid",state,prior+1,Instant.parse(updated),execution.get("id"));execution.set("executionState",state.deepCopy());execution.put("executionStateVersion",prior+1);execution.put("executionStateUpdatedAt",updated);result.put("disposition","applied");result.put("resultVersion",prior+1);return result;}
    @Override public void proposePlan(Connection c,String execution,JsonNode output,String source){plans.proposeWithManager(c,execution,output,source);}
    @Override public void recordDelegation(Connection c,ObjectNode attempt,ObjectNode step,JsonNode observations){delegation.recordObservations(c,attempt,step,observations);}
    @Override public JsonNode completeEfficiency(JsonNode stored,ObjectNode result,ObjectNode attempt){if(stored==null||stored.isNull())return NullNode.instance;try{ContextDomain.parseEfficiency(stored);}catch(RuntimeException e){return stored.deepCopy();}return ContextDomain.complete(stored,result.get("usage"),Instant.now().toString(),Json.text(attempt,"dispatchedAt",Json.text(attempt,"createdAt",Instant.now().toString())));}
    @Override public void expireApprovals(Instant now){approvals.expireDue(null,now,100);}
    @Override public void expireDelegation(Instant now){delegation.expireDue(null,now,100);}
    @Override public void cancelOrphans(int limit){delegation.cancelOrphans(limit);}
    private static AuthorityFailure failure(AuthorityError e,String disposition){return new AuthorityFailure(e.code,disposition,e.getMessage());}
}
